class Solution:
    def amountPainted(self, paint: list[list[int]]) -> list[int]:
        seen = set()
        answer = []
        for start, end in paint:
            fresh = 0
            for x in range(start, end):
                if x not in seen:
                    seen.add(x)
                    fresh += 1
            answer.append(fresh)
        return answer

