class Solution:
    def amountPainted(self, paint: list[list[int]]) -> list[int]:
        parent = {}

        def find(x):
            if x not in parent:
                parent[x] = x
                return x
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        answer = []
        for start, end in paint:
            fresh = 0
            x = find(start)
            while x < end:
                fresh += 1
                parent[x] = find(x + 1)
                x = find(x)
            answer.append(fresh)
        return answer

